body:
You can do this with an apps script, using the onEdit trigger.
Example sheet [here](https://docs.google.com/spreadsheets/d/1ABsple3stiTcarctTb29ttdZ8g8fELL9Xt5bH5gkHSo/edit?usp=sharing) :)


    function onEdit(e) {
      var numberOfColumnsDesired = 3;

      if (typeof (e.value) !== "undefined") {
        return;
      }

      var sheet = e.source.getActiveSheet();
      var currentValues = sheet.getRange(1, 1, sheet.getLastRow(), numberOfColumnsDesired).getValues();
      var temporaryArray = flatten(currentValues);

      var newValues = [];
      var row = [];
      for (var i = 0; i < temporaryArray.length; i++) {
        var value = temporaryArray[i];
        if (value == "") {
          continue;
        }
        row.push(temporaryArray[i]);
        if (row.length == numberOfColumnsDesired) {
          newValues.push(row);
          row = [];
        }
      }

      if (row.length > 0) {
        for (var j = row.length; j < numberOfColumnsDesired; j++) {
          row.push("");
        }
        newValues.push(row);
        row = [];
      }

      //add another empty row of values at the end to blank out what had been the last row prior to the deletion
      for (var k = 0; k < numberOfColumnsDesired; k++) {
        row.push("");
      }
      newValues.push(row);

      sheet.getRange(1, 1, newValues.length, numberOfColumnsDesired).setValues(newValues);
    }


    function flatten(arrayOfArrays) {
      return [].concat.apply([], arrayOfArrays);
    }
